window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d0e75c6993458995"]={"versions": [{"id": "FIG-d0e75c6993458995", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methoden- und Aktivitätsdiagramm der AUTOSAR Adaptive Platform (Methodology Workflow) zur Phase „Deploy Software Package on Machine“. Das Diagramm beschreibt die Aktivität „Set Up Machine“ mit den erforderlichen Eingangs- und Ausgangs-Artefakten (Work Products) zur Vorbereitung einer ECU vor dem eigentlichen Software-Deployment.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität (Activity):</strong></li>\n<li><code>Set Up Machine</code>: Zentrale Transformationsaktivität zur Initialisierung und Konfiguration der Maschine.</li>\n<li><strong>Eingangs-Artefakte (Input Work Products):</strong></li>\n<li><code>Machine Manifest</code> (Kardinalität: <code>1</code>, Stereotyp: <code>«input»</code>): Spezifiziert die Konfigurationseinstellungen für die Instanziierung der Adaptive Platform auf der Maschine.</li>\n<li><code>Operating System for...</code> (vollständig: <em>Operating System for Adaptive Platform</em>, Kardinalität: <code>1..*</code>, Stereotyp: <code>«input»</code>): Bereitzustellendes Betriebssystem bzw. OS-Bestandteile für die Adaptive Platform.</li>\n<li><strong>Ausgangs-Artefakt (Output Work Product):</strong></li>\n<li><code>Configured Adaptive ECU</code> (Kardinalität: <code>1</code>, Stereotyp: <code>«output»</code>): Die fertig aufgesetzte, konfigurierte Adaptive ECU mit installiertem Betriebssystem als Grundlage für spätere Software-Uploads.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Aktivität <code>Set Up Machine</code> konsumiert genau ein <code>Machine Manifest</code> sowie ein oder mehrere OS-Artefakte (<code>Operating System for...</code>, Kardinalität <code>1..*</code>).</li>\n<li>Auf Basis der im Manifest definierten Konfigurationseinstellungen wird die Maschine eingerichtet und das Betriebssystem installiert.</li>\n<li>Als Ergebnis wird genau eine einsatzbereite <code>Configured Adaptive ECU</code> erzeugt, auf die anschließend Anwendungs- und Plattform-Softwarepakete aufgespielt werden können.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität ist normativ durch [TR_AMETH_00031] geregelt (Traceability zu <code>RS_METH_00205</code>, <code>RS_METH_00204</code>). Dieser Initialisierungsschritt erfolgt unabhängig von anwendungs- und plattformspezifischer Software. Durch die Kardinalität <code>1..*</code> am OS-Eingang können potentiell mehrere OS-Artefakte oder Betriebssystem-Bestandteile in den Setup-Prozess einfließen.</p>"}, {"id": "FIG-f8afef6b347df414", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methoden- und Aktivitätsdiagramm der AUTOSAR Adaptive Platform (Methodology Workflow) zur Phase „Deploy Software Package on Machine“. Das Diagramm beschreibt die Aktivität „Set Up Machine“ mit den erforderlichen Eingangs- und Ausgangs-Artefakten (Work Products) zur Vorbereitung einer ECU vor dem eigentlichen Software-Deployment.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität (Activity):</strong></li>\n<li><code>Set Up Machine</code>: Zentrale Transformationsaktivität zur Initialisierung und Konfiguration der Maschine.</li>\n<li><strong>Eingangs-Artefakte (Input Work Products):</strong></li>\n<li><code>Machine Manifest</code> (Kardinalität: <code>1</code>, Stereotyp: <code>«input»</code>): Spezifiziert die Konfigurationseinstellungen für die Instanziierung der Adaptive Platform auf der Maschine.</li>\n<li><code>Operating System for...</code> (vollständig: <em>Operating System for Adaptive Platform</em>, Kardinalität: <code>1</code>, Stereotyp: <code>«input»</code>): Bereitzustellendes Betriebssystem für die Adaptive Platform.</li>\n<li><strong>Ausgangs-Artefakt (Output Work Product):</strong></li>\n<li><code>Configured Adaptive ECU</code> (Kardinalität: <code>1</code>, Stereotyp: <code>«output»</code>): Die fertig aufgesetzte, konfigurierte Adaptive ECU mit installiertem Betriebssystem als Grundlage für spätere Software-Uploads.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Aktivität <code>Set Up Machine</code> konsumiert genau ein <code>Machine Manifest</code> und genau ein Betriebssystem-Artefakt (<code>Operating System for...</code>, Kardinalität <code>1</code>).</li>\n<li>Auf Basis der im Manifest definierten Konfigurationseinstellungen wird die Maschine eingerichtet und das Betriebssystem installiert.</li>\n<li>Als Ergebnis wird genau eine einsatzbereite <code>Configured Adaptive ECU</code> erzeugt, auf die anschließend Anwendungs- und Plattform-Softwarepakete aufgespielt werden können.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität ist normativ durch [TR_AMETH_00031] geregelt (Traceability zu <code>RS_METH_00205</code>, <code>RS_METH_00204</code>). Dieser Initialisierungsschritt erfolgt unabhängig von anwendungs- und plattformspezifischer Software. Für das Aufsetzen der Maschine ist exakt ein Betriebssystem-Artefakt (Kardinalität <code>1</code>) als Eingabe gefordert.</p>"}], "trans": [{"from": "FIG-d0e75c6993458995", "to": "FIG-f8afef6b347df414", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Unterer Eingangs-Work-Product („Operating System for...“): Kardinalität von <code>1..*</code> auf <code>1</code> geändert.</li>\n</ul>"}]};
